import json
from datetime import datetime, timezone
from decimal import Decimal

def read_csv(file_path):
    transactions = {}
    with open(file_path, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            tx_id = row['tx_id']
            timestamp = row['timestamp'] + 'Z'
            amount = row['amount']
            status = row['status']
            timestamp = datetime.fromisoformat(timestamp)
            amount = Decimal(amount)
            if tx_id in transactions or timestamp > transactions[tx_id]['timestamp']:
                transactions[tx_id] = {'timestamp': timestamp, 'amount': amount, 'status': status}
    return transactions

def reconcile(transactions):
    total_valid_amount = Decimal('0.00')
    valid_count = 0
    failed_count = 0
    for tx_id, tx in transactions.items():
        if tx['status'] == 'SUCCESS':
            total_valid_amount += tx['amount']
            valid_count += 1
        elif tx['status'] == 'FAILED':
            failed_count += 1
    return {'total_valid_amount': round(total_valid_amount, 2), 'valid_count': valid_count, 'failed_count': failed_count}

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python3 reconcile.py <csv_file>', file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    transactions = read_csv(file_path)
    result = reconcile(transactions)
    print(json.dumps(result))"
